from __future__ import absolute_import
from builtins import object
import json
import os
from taf.ul.trs_e2e_fw.lib.scf_parser.lxml_parse import lxml_parse
from taf.ul.trs_e2e_fw.lib.utils.decorators import check_rat
from taf.ul.trs_e2e_fw.lib.scf_parser.exceptions import ValueNotFoundException, XpathNotInMapping


class ScfParser(object):

    """

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, scf_file):
        self.scf_file = scf_file
        self.xpath_dict = self._get_xpath_mapping()
        # print 'xpath_dict', self.xpath_dict
        self.xml_parser = lxml_parse()
        self.parsed_scf_obj = self.xml_parser.get_parsed_xml_object(self.scf_file)

    def _get_xpath_mapping(self):
        base_dir = os.path.dirname(__file__)
        resource_file = os.path.join(base_dir, 'resources', 'xpath_mapping.json')
        #print resource_file
        with open(resource_file) as json_file:
            xpath_mapping = json.load(json_file)['xpath_mapping']
        return xpath_mapping

    def get_value_by_xpath(self, xpath_name):
        xpath = self._get_xpath(xpath_name)
        # print 'xpath', xpath
        value = self.xml_parser.get_element_by_xpath(self.parsed_scf_obj, xpath)
        if value is not None and len(value) > 0:
            return value[0]
        raise ValueNotFoundException('for xpath: {}'.format(xpath))

    def get_value_from_distname_by_iteration(self, distname, paramname):
        value = self.xml_parser.get_value_by_iteration(self.parsed_scf_obj,
                                                       distname, paramname)
        return value

    def _get_xpath(self, xpath_name):
        try:
            return self.xpath_dict[xpath_name]
        except KeyError:
            raise XpathNotInMapping(xpath_name)

    def get_full_distname(self, distname_suffix):
        return self.xml_parser.get_full_distname(self.parsed_scf_obj, distname_suffix)

    def get_full_distname_list_by_regx(self, distname_suffix):
        return self.xml_parser.get_full_distname_list_by_regx(self.parsed_scf_obj, distname_suffix)

    def get_list_by_classname(self,classname):
        return self.xml_parser.get_list_of_nodes_by_xpath(self.parsed_scf_obj, self._get_xpath(classname))

    @check_rat
    def get_distname_from_parameter_by_iteration(self, **kwargs):
        param_name = kwargs.get("param_name")
        param_val = kwargs.get("param_val")
        return self.xml_parser.get_distname_from_parameter_by_iteration(self.parsed_scf_obj, param_name, param_val)
